 "content": "def transform(grid):
    """Extend the horizontal bars vertically through their aligned gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A guide column is marked by a vertical colored line in the lower part
    # of the grid. The horizontal bars have matching one-cell gaps in it.
    guide_cols = set()
    for c in range(1, w - 1):
        if any(grid[r][c] != 0 and grid[r][c - 1] == 0 and grid[r][c + 1] == 0
               for r in range(h - 1, max(-1, h - 6), -1)):
            guide_cols.add(c)

    for c in guide_cols:
        marks = []
        for r in range(h):
            if grid[r][c] == 0 and grid[r][c - 1] != 0 and grid[r][c + 1] != 0:
                # The gap belongs to a bar only when both sides carry the same color.
                if grid[r][c - 1] == grid[r][c + 1]:
                    marks.append((r, grid[r][c - 1]))
        previous = -1
        for r, color in marks:
            for y in range(previous + 1, r + 1):
                out[y][c] = color
            previous = r
    return out
