    """Project the horizontal bars through aligned gaps along lower guides."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Vertical guide columns are indicated by isolated colored cells near the bottom.
    guide_cols = []
    for c in range(1, w - 1):
        guide_color = next((grid[r][c] for r in range(h - 1, max(-1, h - 7), -1)
