        if guide_color is None:
            continue

        # Each horizontal bar's one-cell gap marks the color for the vertical
        # segment from the previous boundary through this row.
        marks = []
        for r in range(h):
            left, right = grid[r][c - 1], grid[r][c + 1]
            if grid[r][c] == 0 and left != 0 and left == right:
                marks.append((r, left))
        if not marks:
            continue
        guide_cols.append((c, guide_color, marks))

    for c, guide_color, marks in guide_cols:
        start = 0
        for r, color in marks:
            for y in range(start, r + 1):
                out[y][c] = color
            start = r + 1
        # Continue the lower vertical guide through the remaining interval.
        for y in range(start, h):
            out[y][c] = guide_color
    return out
